#!/bin/bash
#===============================================================================
# DeepTuneIO Analyzer — Module 04: Collect SLURM seff reports
#
# CLUSTER-SIDE ONLY.
#
# Purpose
# -------
# Collect SLURM efficiency reports using `seff` for the JobIDs contained in a
# manifest generated by the DeepTuneIO Analyzer workflow.
#
# This script:
#   - does NOT launch compute jobs;
#   - does NOT modify the original experiments;
#   - does NOT perform performance analysis;
#   - only queries SLURM accounting information through `seff`.
#
# Application and mapping are supplied explicitly as command-line parameters.
# They are recorded in the generated report names so reports from different
# applications/mappings can coexist in the same output directory.
#
# Recommended execution location
# ------------------------------
# Run from a login/service node where `seff` is available and permitted by the
# HPC center.
#
# Usage
# -----
#   ./04_collect_seff_reports_args.sh \
#       --jobids JOBIDS.txt \
#       --output-dir OUTPUT_DIR \
#       --application APPLICATION \
#       --mapping MAPPING
#
# Example
# -------
#   ./04_collect_seff_reports_args.sh \
#       --jobids 03_jobids_JCC24.txt \
#       --output-dir ./seff \
#       --application DeepTuneIO-Training \
#       --mapping HDF5_Distrib_Shared_TinyImageNet-200
#
# Output naming
# -------------
#   seff_<application>_<mapping>_<jobid>.txt
#
# Example:
#   seff_DeepTuneIO-Training_HDF5_Distrib_Shared_TinyImageNet-200_8374752.txt
#
# Version: 2.0.0
#===============================================================================

set -euo pipefail

VERSION="2.0.0"

JOBID_FILE=""
OUTPUT_DIR=""
APPLICATION=""
MAPPING=""

usage() {
    cat <<EOF
DeepTuneIO Analyzer — Module 04: Collect SLURM seff reports
Version: ${VERSION}

Usage:
  $0 --jobids FILE --output-dir DIR --application NAME --mapping NAME

Required arguments:
  --jobids FILE          Text file containing one SLURM JobID per line.
  --output-dir DIR       Directory where seff reports will be written.
  --application NAME     Application/campaign name.
  --mapping NAME         Mapping/dataset/configuration label.

Optional arguments:
  -h, --help             Show this help message.
  --version              Show script version.

Example:
  $0 \
    --jobids 03_jobids_JCC24.txt \
    --output-dir ./seff \
    --application DeepTuneIO-Training \
    --mapping HDF5_Distrib_Shared_TinyImageNet-200
EOF
}

# Convert a metadata label into a filesystem-safe component while preserving
# useful experiment information.
sanitize_label() {
    local value="$1"

    value="${value// /_}"
    value="${value//\//_}"
    value="${value//\\/_}"
    value="${value//:/_}"

    # Keep letters, numbers, dot, underscore and hyphen.
    printf '%s' "${value}" | sed 's/[^[:alnum:]._-]/_/g'
}

# -----------------------------------------------------------------------------
# Parse command-line arguments
# -----------------------------------------------------------------------------
while [[ $# -gt 0 ]]; do
    case "$1" in
        --jobids)
            [[ $# -ge 2 ]] || { echo "ERROR: --jobids requires a value." >&2; exit 1; }
            JOBID_FILE="$2"
            shift 2
            ;;
        --output-dir)
            [[ $# -ge 2 ]] || { echo "ERROR: --output-dir requires a value." >&2; exit 1; }
            OUTPUT_DIR="$2"
            shift 2
            ;;
        --application)
            [[ $# -ge 2 ]] || { echo "ERROR: --application requires a value." >&2; exit 1; }
            APPLICATION="$2"
            shift 2
            ;;
        --mapping)
            [[ $# -ge 2 ]] || { echo "ERROR: --mapping requires a value." >&2; exit 1; }
            MAPPING="$2"
            shift 2
            ;;
        -h|--help)
            usage
            exit 0
            ;;
        --version)
            echo "${VERSION}"
            exit 0
            ;;
        *)
            echo "ERROR: Unknown argument: $1" >&2
            echo
            usage >&2
            exit 1
            ;;
    esac
done

# -----------------------------------------------------------------------------
# Validate required arguments
# -----------------------------------------------------------------------------
[[ -n "${JOBID_FILE}" ]] || {
    echo "ERROR: --jobids is required." >&2
    usage >&2
    exit 1
}

[[ -n "${OUTPUT_DIR}" ]] || {
    echo "ERROR: --output-dir is required." >&2
    usage >&2
    exit 1
}

[[ -n "${APPLICATION}" ]] || {
    echo "ERROR: --application is required." >&2
    usage >&2
    exit 1
}

[[ -n "${MAPPING}" ]] || {
    echo "ERROR: --mapping is required." >&2
    usage >&2
    exit 1
}

command -v seff >/dev/null 2>&1 || {
    echo "ERROR: seff is not available in PATH." >&2
    exit 1
}

[[ -f "${JOBID_FILE}" ]] || {
    echo "ERROR: JobID manifest not found: ${JOBID_FILE}" >&2
    exit 1
}

mkdir -p "${OUTPUT_DIR}"

APPLICATION_SAFE="$(sanitize_label "${APPLICATION}")"
MAPPING_SAFE="$(sanitize_label "${MAPPING}")"

generated=0
skipped=0
failed=0
invalid=0
total=0

echo "============================================================================="
echo "DeepTuneIO Analyzer — Module 04: Collect SLURM seff reports"
echo "============================================================================="
echo "Version     : ${VERSION}"
echo "Application : ${APPLICATION}"
echo "Mapping     : ${MAPPING}"
echo "JobID file  : ${JOBID_FILE}"
echo "Output dir  : ${OUTPUT_DIR}"
echo "============================================================================="

# -----------------------------------------------------------------------------
# Process JobIDs
# -----------------------------------------------------------------------------
while IFS= read -r jobid || [[ -n "${jobid}" ]]; do
    # Remove CR characters from Windows-formatted manifests and trim whitespace.
    jobid="${jobid//$'\r'/}"
    jobid="${jobid//[[:space:]]/}"

    [[ -z "${jobid}" ]] && continue

    ((total+=1))

    if [[ ! "${jobid}" =~ ^[0-9]+$ ]]; then
        echo "WARNING: invalid JobID '${jobid}', skipped."
        ((invalid+=1))
        continue
    fi

    outfile="${OUTPUT_DIR}/seff_${APPLICATION_SAFE}_${MAPPING_SAFE}_${jobid}.txt"

    if [[ -s "${outfile}" ]]; then
        echo "SKIP ${jobid}: report already exists."
        ((skipped+=1))
        continue
    fi

    tmp="${outfile}.tmp"

    # Remove an interrupted temporary file from an earlier run.
    rm -f "${tmp}"

    echo "Collecting JobID ${jobid} ..."

    if seff "${jobid}" > "${tmp}" 2>&1; then
        if grep -qiE 'Job[[:space:]]*ID:' "${tmp}"; then
            mv "${tmp}" "${outfile}"
            echo "OK   ${jobid}: ${outfile}"
            ((generated+=1))
        else
            echo "WARNING: seff returned no recognizable report for ${jobid}"
            mv "${tmp}" "${outfile}.failed"
            ((failed+=1))
        fi
    else
        echo "WARNING: seff failed for ${jobid}"
        mv "${tmp}" "${outfile}.failed"
        ((failed+=1))
    fi

done < "${JOBID_FILE}"

# -----------------------------------------------------------------------------
# Execution summary
# -----------------------------------------------------------------------------
echo
echo "============================================================================="
echo "seff collection summary"
echo "============================================================================="
echo "Application : ${APPLICATION}"
echo "Mapping     : ${MAPPING}"
echo "Total       : ${total}"
echo "Generated   : ${generated}"
echo "Skipped     : ${skipped}"
echo "Invalid     : ${invalid}"
echo "Failed      : ${failed}"
echo "Output      : ${OUTPUT_DIR}"
echo "============================================================================="

# Preserve partial results.
# Return non-zero only when no valid report was generated or reused.
if (( generated == 0 && skipped == 0 )); then
    exit 2
fi

exit 0
